/* Keep the reading surface visible. Project-specific research motion is handled separately. */
(()=>{const header=document.querySelector('.topbar'),reflection=document.querySelector('#reflection');if(!reflection||!header)return;let ticking=false;const update=()=>header.classList.toggle('is-light',reflection.getBoundingClientRect().top<=64);addEventListener('scroll',()=>{if(!ticking){ticking=true;requestAnimationFrame(()=>{update();ticking=false})}},{passive:true});addEventListener('pageshow',update);update()})();
